**Interview memory:** Two things varying at once? Stop inheriting along both axes and make one of them a field.

**Interview answer:** Memento captures an object's internal state so it can be restored later, **without exposing that state to anyone else**. The object hands out a sealed token; only the object that produced it can read it back.

The "without exposing" clause is the whole pattern. Anyone can add a `GetState()`/`SetState()` pair, but that breaks encapsulation permanently - every caller now depends on the shape of your internals and you can never change them. A memento is opaque to whoever stores it.

**What to say while explaining:** point at the `History` class below. It holds a stack of snapshots and cannot read a single field out of one. That guarantee is what you are buying.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class TextEditor
{
    // Internals nobody outside should depend on.
    private string _content = "";
    private int _caret;

    public void Type(string text)
    {
        _content = _content.Insert(_caret, text);
        _caret += text.Length;
    }

    public void MoveCaretToStart() => _caret = 0;

    public override string ToString() => $"'{_content}' caret={_caret}";

    // The memento: opaque from the outside, readable only by TextEditor.
    public sealed class Snapshot
    {
        internal readonly string Content;
        internal readonly int Caret;
        internal Snapshot(string content, int caret) { Content = content; Caret = caret; }
    }

    public Snapshot Save() => new Snapshot(_content, _caret);

    public void Restore(Snapshot snapshot)
    {
        _content = snapshot.Content;
        _caret = snapshot.Caret;
    }
}

// The caretaker stores snapshots but cannot look inside them.
public class History
{
    private readonly Stack<TextEditor.Snapshot> _stack = new Stack<TextEditor.Snapshot>();
    public void Push(TextEditor.Snapshot s) => _stack.Push(s);
    public TextEditor.Snapshot Pop() => _stack.Count > 0 ? _stack.Pop() : null;
    public int Count => _stack.Count;
}

public static class Program
{
    public static void Main()
    {
        var editor = new TextEditor();
        var history = new History();

        history.Push(editor.Save());
        editor.Type("Dear Sam");
        Console.WriteLine($"1. {editor}");

        history.Push(editor.Save());
        editor.MoveCaretToStart();
        editor.Type(">> ");
        Console.WriteLine($"2. {editor}");

        history.Push(editor.Save());
        editor.Type("URGENT ");
        Console.WriteLine($"3. {editor}");

        Console.WriteLine();
        Console.WriteLine($"history holds {history.Count} snapshots, and can read none of them.");

        while (history.Count > 0)
        {
            editor.Restore(history.Pop());
            Console.WriteLine($"   restored -> {editor}");
        }
    }
}
```

**Output**

```
1. 'Dear Sam' caret=8
2. '>> Dear Sam' caret=3
3. '>> URGENT Dear Sam' caret=10

history holds 3 snapshots, and can read none of them.
   restored -> '>> Dear Sam' caret=3
   restored -> 'Dear Sam' caret=8
   restored -> '' caret=0
```

**Interview memory:** A memento is a sealed envelope: the caretaker can hold it and hand it back, but only the originator can open it.

**Interview answer:** Mediator replaces many-to-many references between components with a hub. Instead of every component holding a reference to every other one, each holds one reference to the mediator, and the mediator owns the interaction rules.

The symptom it fixes is a screen where every control knows about every other control: the country dropdown enables the region dropdown, which enables the submit button. That knowledge is duplicated across controls and breaks the moment someone adds a field. Move it into one place and each control goes back to being dumb.

**What to say while explaining:** the controls below never name each other. Adding a fourth control changes the mediator and nothing else.

**Program**

```csharp
using System;
using System.Collections.Generic;

public interface IMediator
{
    void Notify(Control sender, string signal);
}

public abstract class Control
{
    public string Name { get; }
    public bool Enabled { get; set; }
    protected IMediator Mediator;
    protected Control(string name, IMediator mediator) { Name = name; Mediator = mediator; }
    public override string ToString() => $"{Name}={(Enabled ? "enabled" : "disabled")}";
}

public class Dropdown : Control
{
    public string Selected { get; private set; }
    public Dropdown(string name, IMediator m) : base(name, m) { }

    public void Select(string value)
    {
        if (!Enabled) { Console.WriteLine($"  {Name}: ignored, control is disabled"); return; }
        Selected = value;
        Console.WriteLine($"  {Name}: selected '{value}'");
        Mediator.Notify(this, "changed");        // tells the hub, not its neighbours
    }
}

public class Button : Control
{
    public Button(string name, IMediator m) : base(name, m) { }
    public void Click() => Console.WriteLine(Enabled ? $"  {Name}: submitted" : $"  {Name}: click ignored, still disabled");
}

// Every interaction rule lives here, and nowhere else.
public class OrderFormMediator : IMediator
{
    public Dropdown Country { get; }
    public Dropdown Region { get; }
    public Button Submit { get; }

    public OrderFormMediator()
    {
        Country = new Dropdown("country", this) { Enabled = true };
        Region  = new Dropdown("region", this)  { Enabled = false };
        Submit  = new Button("submit", this)    { Enabled = false };
    }

    public void Notify(Control sender, string signal)
    {
        if (sender == Country && signal == "changed")
        {
            Region.Enabled = true;
            Submit.Enabled = false;      // country changed, so the region is stale again
        }
        else if (sender == Region && signal == "changed")
        {
            Submit.Enabled = true;
        }
    }

    public string State() => string.Join(", ", new List<Control> { Country, Region, Submit });
}

public static class Program
{
    public static void Main()
    {
        var form = new OrderFormMediator();
        Console.WriteLine("initial : " + form.State());

        Console.WriteLine("user clicks submit early:");
        form.Submit.Click();

        Console.WriteLine("user picks a region before a country:");
        form.Region.Select("Yorkshire");

        Console.WriteLine("user picks a country:");
        form.Country.Select("UK");
        Console.WriteLine("state   : " + form.State());

        Console.WriteLine("user picks a region:");
        form.Region.Select("Yorkshire");
        Console.WriteLine("state   : " + form.State());

        Console.WriteLine("user submits:");
        form.Submit.Click();

        Console.WriteLine("user changes country again:");
        form.Country.Select("Ireland");
        Console.WriteLine("state   : " + form.State());
        form.Submit.Click();
    }
}
```

**Output**

```
initial : country=enabled, region=disabled, submit=disabled
user clicks submit early:
  submit: click ignored, still disabled
user picks a region before a country:
  region: ignored, control is disabled
user picks a country:
  country: selected 'UK'
state   : country=enabled, region=enabled, submit=disabled
user picks a region:
  region: selected 'Yorkshire'
state   : country=enabled, region=enabled, submit=enabled
user submits:
  submit: submitted
user changes country again:
  country: selected 'Ireland'
state   : country=enabled, region=enabled, submit=disabled
  submit: click ignored, still disabled
```

**Interview memory:** Mediator turns an n-to-n web of references into n spokes and one hub that owns the rules.

**Interview answer:** Visitor lets you add a new *operation* to a fixed set of node types without editing those types. Each node implements `Accept(visitor)` and calls back `visitor.VisitX(this)` - the callback resolves the concrete node type, which is the "double dispatch" part: the method that runs depends on both the visitor type and the node type.

The trade it makes is precise and worth stating: **adding operations is cheap, adding node types is expensive.** A new visitor is one class. A new node type forces a change to the visitor interface and to every existing visitor. Use it when the node hierarchy is stable and operations keep arriving - compilers, ASTs, expression trees, document models.

**What to say while explaining:** acknowledge that C# pattern matching is often the better answer, then give the reason to still use Visitor - the compiler forces every visitor to handle every node, so a new node type cannot be silently forgotten.

**Program**

```csharp
using System;

public interface IVisitor<T>
{
    T VisitNumber(NumberExpr n);
    T VisitAdd(AddExpr a);
    T VisitMultiply(MultiplyExpr m);
}

public abstract class Expr
{
    public abstract T Accept<T>(IVisitor<T> visitor);
}

public class NumberExpr : Expr
{
    public double Value { get; }
    public NumberExpr(double v) { Value = v; }
    public override T Accept<T>(IVisitor<T> v) => v.VisitNumber(this);
}

public class AddExpr : Expr
{
    public Expr Left { get; } public Expr Right { get; }
    public AddExpr(Expr l, Expr r) { Left = l; Right = r; }
    public override T Accept<T>(IVisitor<T> v) => v.VisitAdd(this);
}

public class MultiplyExpr : Expr
{
    public Expr Left { get; } public Expr Right { get; }
    public MultiplyExpr(Expr l, Expr r) { Left = l; Right = r; }
    public override T Accept<T>(IVisitor<T> v) => v.VisitMultiply(this);
}

// Operation 1 - added without touching any node class.
public class Evaluator : IVisitor<double>
{
    public double VisitNumber(NumberExpr n) => n.Value;
    public double VisitAdd(AddExpr a) => a.Left.Accept(this) + a.Right.Accept(this);
    public double VisitMultiply(MultiplyExpr m) => m.Left.Accept(this) * m.Right.Accept(this);
}

// Operation 2 - again, no node class changed.
public class Printer : IVisitor<string>
{
    public string VisitNumber(NumberExpr n) => n.Value.ToString("0.##");
    public string VisitAdd(AddExpr a) => $"({a.Left.Accept(this)} + {a.Right.Accept(this)})";
    public string VisitMultiply(MultiplyExpr m) => $"{m.Left.Accept(this)} * {m.Right.Accept(this)}";
}

// Operation 3 - a completely different shape of result.
public class NodeCounter : IVisitor<int>
{
    public int VisitNumber(NumberExpr n) => 1;
    public int VisitAdd(AddExpr a) => 1 + a.Left.Accept(this) + a.Right.Accept(this);
    public int VisitMultiply(MultiplyExpr m) => 1 + m.Left.Accept(this) + m.Right.Accept(this);
}

public static class Program
{
    public static void Main()
    {
        // (2 + 3) * (4 + 1)
        Expr tree = new MultiplyExpr(
            new AddExpr(new NumberExpr(2), new NumberExpr(3)),
            new AddExpr(new NumberExpr(4), new NumberExpr(1)));

        Console.WriteLine($"printed  : {tree.Accept(new Printer())}");
        Console.WriteLine($"evaluated: {tree.Accept(new Evaluator())}");
        Console.WriteLine($"nodes    : {tree.Accept(new NodeCounter())}");

        Console.WriteLine();
        Console.WriteLine("three operations, three classes, and not one edit to the node types.");
    }
}
```

**Output**

```
printed  : (2 + 3) * (4 + 1)
evaluated: 25
nodes    : 7

three operations, three classes, and not one edit to the node types.
```

**Interview memory:** Visitor flips the cost: operations become cheap, node types become expensive. Take that deal only when the nodes have stopped changing.

**Interview answer:** Interpreter defines a grammar as a class hierarchy - one class per rule - and evaluates a sentence by walking the resulting tree. It is Composite plus an `Evaluate` method that takes a context.

It turns up in real systems as a small rules or filter language: a discount rule, a feature-flag condition, a search filter typed by a user. You build the tree once and evaluate it per record.

It is rare because it only pays off for a *small, stable* grammar. Anything larger and a real parser, or an existing expression library, beats hand-writing a class per production rule.

**What to say while explaining:** point out that the rule below could equally have been loaded from a database row - that is the actual reason anyone builds this, because pricing then changes without a redeploy.

**Program**

```csharp
using System;
using System.Collections.Generic;

public class Context
{
    private readonly Dictionary<string, object> _values = new Dictionary<string, object>();
    public Context Set(string key, object value) { _values[key] = value; return this; }
    public object Get(string key) => _values.TryGetValue(key, out var v) ? v : null;
    public override string ToString()
    {
        var parts = new List<string>();
        foreach (var kv in _values) parts.Add($"{kv.Key}={kv.Value}");
        return string.Join(", ", parts);
    }
}

public interface IRule { bool Evaluate(Context c); string Describe(); }

public class GreaterThan : IRule
{
    private readonly string _field; private readonly decimal _limit;
    public GreaterThan(string field, decimal limit) { _field = field; _limit = limit; }
    public bool Evaluate(Context c) => Convert.ToDecimal(c.Get(_field) ?? 0m) > _limit;
    public string Describe() => $"{_field} > {_limit}";
}

public class EqualsRule : IRule
{
    private readonly string _field; private readonly string _value;
    public EqualsRule(string field, string value) { _field = field; _value = value; }
    public bool Evaluate(Context c) => string.Equals(Convert.ToString(c.Get(_field)), _value, StringComparison.OrdinalIgnoreCase);
    public string Describe() => $"{_field} == '{_value}'";
}

public class And : IRule
{
    private readonly IRule _l, _r;
    public And(IRule l, IRule r) { _l = l; _r = r; }
    public bool Evaluate(Context c) => _l.Evaluate(c) && _r.Evaluate(c);
    public string Describe() => $"({_l.Describe()} AND {_r.Describe()})";
}

public class Or : IRule
{
    private readonly IRule _l, _r;
    public Or(IRule l, IRule r) { _l = l; _r = r; }
    public bool Evaluate(Context c) => _l.Evaluate(c) || _r.Evaluate(c);
    public string Describe() => $"({_l.Describe()} OR {_r.Describe()})";
}

public class Not : IRule
{
    private readonly IRule _inner;
    public Not(IRule inner) { _inner = inner; }
    public bool Evaluate(Context c) => !_inner.Evaluate(c);
    public string Describe() => $"NOT {_inner.Describe()}";
}

public static class Program
{
    public static void Main()
    {
        // "free delivery when the basket is over 50 AND the customer is a member or collecting,
        //  but never for offshore regions"
        IRule freeDelivery = new And(
            new And(
                new GreaterThan("total", 50m),
                new Or(new EqualsRule("tier", "member"), new EqualsRule("fulfilment", "collect"))),
            new Not(new EqualsRule("region", "offshore")));

        Console.WriteLine("rule: " + freeDelivery.Describe());
        Console.WriteLine();

        var baskets = new[]
        {
            new Context().Set("total", 80m).Set("tier", "member").Set("fulfilment", "deliver").Set("region", "mainland"),
            new Context().Set("total", 80m).Set("tier", "guest").Set("fulfilment", "deliver").Set("region", "mainland"),
            new Context().Set("total", 80m).Set("tier", "guest").Set("fulfilment", "collect").Set("region", "mainland"),
            new Context().Set("total", 20m).Set("tier", "member").Set("fulfilment", "collect").Set("region", "mainland"),
            new Context().Set("total", 80m).Set("tier", "member").Set("fulfilment", "collect").Set("region", "offshore"),
        };

        foreach (var basket in baskets)
            Console.WriteLine($"{(freeDelivery.Evaluate(basket) ? "FREE " : "     ")} {basket}");
    }
}
```

**Output**

```
rule: ((total > 50 AND (tier == 'member' OR fulfilment == 'collect')) AND NOT region == 'offshore')

FREE  total=80, tier=member, fulfilment=deliver, region=mainland
      total=80, tier=guest, fulfilment=deliver, region=mainland
FREE  total=80, tier=guest, fulfilment=collect, region=mainland
      total=20, tier=member, fulfilment=collect, region=mainland
      total=80, tier=member, fulfilment=collect, region=offshore
```

**Interview memory:** One class per grammar rule, composed into a tree, evaluated against a context. Great for a tiny language, unbearable for a real one.

**Interview answer:** Null Object provides an implementation of an interface that does nothing harmless - a logger that discards, a cache that always misses, a notifier that swallows. You inject it instead of `null`, and every `if (x != null)` in the consumer disappears.

The benefit is fewer branches and no `NullReferenceException`. The consumer no longer has to know that "no logger" is even a possibility.

The caveat is what makes this a good interview question: a null object turns a missing dependency into **silence**. If someone forgets to register the real email sender, the app runs happily and sends nothing. So use it for genuinely optional collaborators and let the essential ones fail loudly at startup.

**What to say while explaining:** name `NullLogger.Instance` and `Array.Empty<T>()` - .NET ships null objects, so this is not academic.

**Program**

```csharp
using System;
using System.Collections.Generic;

public interface IAuditLog { void Record(string action); }

public class ConsoleAuditLog : IAuditLog
{
    public void Record(string action) => Console.WriteLine($"    [audit] {action}");
}

// The null object: same contract, deliberately does nothing.
public sealed class NullAuditLog : IAuditLog
{
    public static readonly NullAuditLog Instance = new NullAuditLog();
    private NullAuditLog() { }
    public void Record(string action) { }
}

// Version 1: defensive null checks everywhere.
public class ServiceWithNullChecks
{
    private readonly IAuditLog _audit;
    public ServiceWithNullChecks(IAuditLog audit) { _audit = audit; }

    public void Transfer(decimal amount)
    {
        if (_audit != null) _audit.Record($"transfer started {amount:0.00}");
        if (amount <= 0)
        {
            if (_audit != null) _audit.Record("rejected: non-positive");
            Console.WriteLine("  rejected");
            return;
        }
        if (_audit != null) _audit.Record("transfer completed");
        Console.WriteLine("  ok");
    }
}

// Version 2: the dependency is never null, so the checks are gone.
public class ServiceWithNullObject
{
    private readonly IAuditLog _audit;
    public ServiceWithNullObject(IAuditLog audit) { _audit = audit ?? NullAuditLog.Instance; }

    public void Transfer(decimal amount)
    {
        _audit.Record($"transfer started {amount:0.00}");
        if (amount <= 0)
        {
            _audit.Record("rejected: non-positive");
            Console.WriteLine("  rejected");
            return;
        }
        _audit.Record("transfer completed");
        Console.WriteLine("  ok");
    }
}

public static class Program
{
    public static void Main()
    {
        Console.WriteLine("with a real audit log:");
        new ServiceWithNullObject(new ConsoleAuditLog()).Transfer(120m);

        Console.WriteLine("with the null object - auditing switched off in config:");
        new ServiceWithNullObject(NullAuditLog.Instance).Transfer(120m);

        Console.WriteLine("passing null - no exception, and no branches in the method:");
        new ServiceWithNullObject(null).Transfer(-5m);

        Console.WriteLine();
        Console.WriteLine("the null-check version behaves the same but carries 4 extra branches:");
        new ServiceWithNullChecks(null).Transfer(-5m);

        Console.WriteLine();
        // Null objects for collections are so common they ship in the framework.
        IEnumerable<string> nothing = Array.Empty<string>();
        Console.WriteLine($"Array.Empty<string>() is a null object too - foreach over it runs {CountLoops(nothing)} times.");
    }

    static int CountLoops(IEnumerable<string> items)
    {
        int n = 0;
        foreach (var item in items) n++;
        return n;
    }
}
```

**Output**

```
with a real audit log:
    [audit] transfer started 120.00
    [audit] transfer completed
  ok
with the null object - auditing switched off in config:
  ok
passing null - no exception, and no branches in the method:
  rejected

the null-check version behaves the same but carries 4 extra branches:
  rejected

Array.Empty<string>() is a null object too - foreach over it runs 0 times.
```

**Interview memory:** A null object is "do nothing, quietly, on purpose". Its danger is the word quietly.

**Interview answer:** Repository hides the data source behind a collection-like interface; Unit of Work makes several repository operations commit or roll back as one transaction.

The honest answer to "is it worth it on top of EF Core" is: **often not**, because `DbSet<T>` is already a repository and `DbContext` is already a unit of work. Wrapping them adds a layer that usually leaks anyway - the moment someone needs `Include`, `AsNoTracking` or a projection, either the interface grows EF-shaped methods or the abstraction is bypassed.

Where it does earn its place: when the domain layer must not reference EF at all, when you want query logic named in domain language (`FindOverdue()` rather than a lambda repeated in six services), or when multiple aggregates must commit atomically and you want that boundary explicit.

**What to say while explaining:** state the trade-off first and then show it, rather than presenting it as automatically good practice. The output below proves the atomic part - a failure mid-way leaves nothing saved.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class Order
{
    public int Id { get; set; }
    public string Customer { get; set; }
    public decimal Total { get; set; }
    public bool Dispatched { get; set; }
}

public class StockItem
{
    public string Sku { get; set; }
    public int Quantity { get; set; }
}

// A repository speaks the domain's language, not the database's.
public interface IOrderRepository
{
    void Add(Order order);
    Order Get(int id);
    IReadOnlyList<Order> FindUndispatchedOver(decimal amount);
}

public interface IStockRepository
{
    StockItem Get(string sku);
    void Reserve(string sku, int quantity);
}

// The unit of work owns the transaction and hands out the repositories.
public interface IUnitOfWork : IDisposable
{
    IOrderRepository Orders { get; }
    IStockRepository Stock { get; }
    void Commit();
}

// --- an in-memory implementation, standing in for EF Core ---
public class FakeDatabase
{
    public List<Order> Orders = new List<Order>();
    public List<StockItem> Stock = new List<StockItem>();
}

public class UnitOfWork : IUnitOfWork
{
    private readonly FakeDatabase _db;
    private readonly List<Action> _pending = new List<Action>();   // nothing is applied until Commit

    public UnitOfWork(FakeDatabase db)
    {
        _db = db;
        Orders = new OrderRepository(db, _pending);
        Stock = new StockRepository(db, _pending);
    }

    public IOrderRepository Orders { get; }
    public IStockRepository Stock { get; }

    public void Commit()
    {
        foreach (var change in _pending) change();
        Console.WriteLine($"  committed {_pending.Count} change(s)");
        _pending.Clear();
    }

    public void Dispose() => _pending.Clear();   // uncommitted work is discarded

    private class OrderRepository : IOrderRepository
    {
        private readonly FakeDatabase _db; private readonly List<Action> _pending;
        public OrderRepository(FakeDatabase db, List<Action> pending) { _db = db; _pending = pending; }

        public void Add(Order order) => _pending.Add(() => _db.Orders.Add(order));
        public Order Get(int id) => _db.Orders.FirstOrDefault(o => o.Id == id);

        // The query has a domain name, so it is written once and tested once.
        public IReadOnlyList<Order> FindUndispatchedOver(decimal amount) =>
            _db.Orders.Where(o => !o.Dispatched && o.Total > amount).ToList();
    }

    private class StockRepository : IStockRepository
    {
        private readonly FakeDatabase _db; private readonly List<Action> _pending;
        public StockRepository(FakeDatabase db, List<Action> pending) { _db = db; _pending = pending; }

        public StockItem Get(string sku) => _db.Stock.First(s => s.Sku == sku);

        public void Reserve(string sku, int quantity)
        {
            var item = Get(sku);
            if (item.Quantity < quantity)
                throw new InvalidOperationException($"only {item.Quantity} of {sku} left, asked for {quantity}");
            _pending.Add(() => item.Quantity -= quantity);
        }
    }
}

public static class Program
{
    static void PlaceOrder(FakeDatabase db, int id, string sku, int qty, decimal total)
    {
        using (var uow = new UnitOfWork(db))
        {
            uow.Orders.Add(new Order { Id = id, Customer = "Acme", Total = total });
            uow.Stock.Reserve(sku, qty);
            uow.Commit();
        }
    }

    public static void Main()
    {
        var db = new FakeDatabase();
        db.Stock.Add(new StockItem { Sku = "WIDGET", Quantity = 5 });

        Console.WriteLine("order 1 - enough stock:");
        PlaceOrder(db, 1, "WIDGET", 3, 300m);
        Console.WriteLine($"  orders={db.Orders.Count} stock={db.Stock[0].Quantity}");

        Console.WriteLine("order 2 - not enough stock:");
        try { PlaceOrder(db, 2, "WIDGET", 10, 900m); }
        catch (InvalidOperationException ex) { Console.WriteLine("  rejected: " + ex.Message); }

        // The order was added to the unit of work before the reservation failed.
        // Because nothing is applied until Commit, it was never saved.
        Console.WriteLine($"  orders={db.Orders.Count} stock={db.Stock[0].Quantity}  (order 2 was NOT saved)");

        Console.WriteLine("query with a domain name:");
        foreach (var o in new UnitOfWork(db).Orders.FindUndispatchedOver(100m))
            Console.WriteLine($"  order {o.Id} for {o.Customer}, {o.Total:0.00}");
    }
}
```

**Output**

```
order 1 - enough stock:
  committed 2 change(s)
  orders=1 stock=2
order 2 - not enough stock:
  rejected: only 2 of WIDGET left, asked for 10
  orders=1 stock=2  (order 2 was NOT saved)
query with a domain name:
  order 1 for Acme, 300.00
```

**Interview memory:** DbContext is already a Unit of Work and DbSet is already a Repository. Add your own only to buy something those two do not give you.

**Interview answer:** CQRS means using a different model to write than to read. Commands change state and return little; queries return shaped data and change nothing. That is the whole idea - it does **not** require event sourcing, message buses or two databases, though all three often turn up alongside it.

The reason it helps is that writes and reads want opposite things. Writes want a normalised aggregate that enforces invariants. Reads want a flat, denormalised shape matched to one screen. Forcing both through one model gives you an entity with lazy-loaded navigation properties that half the app maps away again.

**What to say while explaining:** start at the cheap end - same database, separate command handlers and read DTOs. Then say what you would add and when: a read replica under query load, and a projected read model only when the join cost genuinely hurts. Jumping straight to two databases is the mistake interviewers are listening for.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

// ---------- write side: a real aggregate that protects its invariants ----------
public class Order
{
    private readonly List<(string Sku, int Qty, decimal Price)> _lines = new List<(string, int, decimal)>();

    public Guid Id { get; } = Guid.Empty;
    public string Customer { get; private set; }
    public string Status { get; private set; } = "Draft";

    public Order(string customer) { Customer = customer; }

    public void AddLine(string sku, int qty, decimal price)
    {
        if (Status != "Draft") throw new InvalidOperationException("cannot change a submitted order");
        if (qty <= 0) throw new ArgumentException("quantity must be positive");
        _lines.Add((sku, qty, price));
    }

    public void Submit()
    {
        if (_lines.Count == 0) throw new InvalidOperationException("cannot submit an empty order");
        Status = "Submitted";
    }

    internal IEnumerable<(string Sku, int Qty, decimal Price)> Lines => _lines;
    internal decimal Total => _lines.Sum(l => l.Qty * l.Price);
}

// ---------- commands ----------
public class SubmitOrderCommand { public string Customer; public (string Sku, int Qty, decimal Price)[] Lines; }

public class SubmitOrderHandler
{
    private readonly Store _store;
    public SubmitOrderHandler(Store store) { _store = store; }

    // Returns an identifier, not data. A command is not a query.
    public int Handle(SubmitOrderCommand command)
    {
        var order = new Order(command.Customer);
        foreach (var line in command.Lines) order.AddLine(line.Sku, line.Qty, line.Price);
        order.Submit();
        return _store.Save(order);
    }
}

// ---------- read side: a flat shape built for one screen ----------
public class OrderSummary
{
    public int Id; public string Customer; public int LineCount; public decimal Total; public string Status;
    public override string ToString() => $"#{Id} {Customer,-8} lines={LineCount} total={Total,8:0.00} {Status}";
}

public class OrderSummaryQuery
{
    private readonly Store _store;
    public OrderSummaryQuery(Store store) { _store = store; }

    // No aggregate, no invariants, no change tracking - just the shape the UI wants.
    public IReadOnlyList<OrderSummary> AboveTotal(decimal minimum) =>
        _store.All()
              .Where(kv => kv.Value.Total >= minimum)
              .Select(kv => new OrderSummary
              {
                  Id = kv.Key,
                  Customer = kv.Value.Customer,
                  LineCount = kv.Value.Lines.Count(),
                  Total = kv.Value.Total,
                  Status = kv.Value.Status
              })
              .OrderByDescending(s => s.Total)
              .ToList();
}

public class Store
{
    private readonly Dictionary<int, Order> _orders = new Dictionary<int, Order>();
    private int _next = 100;
    public int Save(Order o) { var id = _next++; _orders[id] = o; return id; }
    public IEnumerable<KeyValuePair<int, Order>> All() => _orders;
}

public static class Program
{
    public static void Main()
    {
        var store = new Store();
        var handler = new SubmitOrderHandler(store);
        var query = new OrderSummaryQuery(store);

        Console.WriteLine("commands (write model enforces the rules):");
        var a = handler.Handle(new SubmitOrderCommand { Customer = "Acme", Lines = new[] { ("WIDGET", 2, 50m), ("BOLT", 10, 1.5m) } });
        var b = handler.Handle(new SubmitOrderCommand { Customer = "Globex", Lines = new[] { ("WIDGET", 1, 50m) } });
        Console.WriteLine($"  created order {a} and order {b}");

        try { handler.Handle(new SubmitOrderCommand { Customer = "Initech", Lines = new (string, int, decimal)[0] }); }
        catch (InvalidOperationException ex) { Console.WriteLine("  rejected: " + ex.Message); }

        try { handler.Handle(new SubmitOrderCommand { Customer = "Initech", Lines = new[] { ("WIDGET", -1, 50m) } }); }
        catch (ArgumentException ex) { Console.WriteLine("  rejected: " + ex.Message); }

        Console.WriteLine();
        Console.WriteLine("query (read model is flat, and knows nothing about invariants):");
        foreach (var summary in query.AboveTotal(40m))
            Console.WriteLine("  " + summary);
    }
}
```

**Output**

```
commands (write model enforces the rules):
  created order 100 and order 101
  rejected: cannot submit an empty order
  rejected: quantity must be positive

query (read model is flat, and knows nothing about invariants):
  #100 Acme     lines=2 total=  115.00 Submitted
  #101 Globex   lines=1 total=   50.00 Submitted
```

**Interview memory:** CQRS is two models, not two databases. Everything else - replicas, projections, event sourcing - is an optional upgrade you justify separately.

**Interview answer:** A specification wraps a single business rule as an object that can answer "does this candidate satisfy me?" - and, crucially, can be combined with other specifications using And, Or and Not.

The problem it solves is a rule that exists in three places in slightly different forms: a validation check in the service, a LINQ predicate in the repository, and an `if` in a report. Name it once as a specification and all three use the same object.

The .NET-specific twist is that a specification built from `Expression<Func<T,bool>>` rather than `Func<T,bool>` can be handed to EF Core and translated into SQL, so the same rule filters in memory *and* in the database.

**What to say while explaining:** show the composition. `activeCustomer.And(highValue).And(notBlocked)` reads like the business sentence, and no new class was needed for the combination.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Linq.Expressions;

public abstract class Specification<T>
{
    public abstract Expression<Func<T, bool>> ToExpression();
    public abstract string Describe();

    public bool IsSatisfiedBy(T candidate) => ToExpression().Compile()(candidate);

    public Specification<T> And(Specification<T> other) => new AndSpecification<T>(this, other);
    public Specification<T> Or(Specification<T> other) => new OrSpecification<T>(this, other);
    public Specification<T> Not() => new NotSpecification<T>(this);
}

public class AndSpecification<T> : Specification<T>
{
    private readonly Specification<T> _l, _r;
    public AndSpecification(Specification<T> l, Specification<T> r) { _l = l; _r = r; }

    public override Expression<Func<T, bool>> ToExpression()
    {
        var p = Expression.Parameter(typeof(T));
        var body = Expression.AndAlso(
            Expression.Invoke(_l.ToExpression(), p),
            Expression.Invoke(_r.ToExpression(), p));
        return Expression.Lambda<Func<T, bool>>(body, p);
    }
    public override string Describe() => $"({_l.Describe()} AND {_r.Describe()})";
}

public class OrSpecification<T> : Specification<T>
{
    private readonly Specification<T> _l, _r;
    public OrSpecification(Specification<T> l, Specification<T> r) { _l = l; _r = r; }

    public override Expression<Func<T, bool>> ToExpression()
    {
        var p = Expression.Parameter(typeof(T));
        var body = Expression.OrElse(
            Expression.Invoke(_l.ToExpression(), p),
            Expression.Invoke(_r.ToExpression(), p));
        return Expression.Lambda<Func<T, bool>>(body, p);
    }
    public override string Describe() => $"({_l.Describe()} OR {_r.Describe()})";
}

public class NotSpecification<T> : Specification<T>
{
    private readonly Specification<T> _inner;
    public NotSpecification(Specification<T> inner) { _inner = inner; }

    public override Expression<Func<T, bool>> ToExpression()
    {
        var p = Expression.Parameter(typeof(T));
        return Expression.Lambda<Func<T, bool>>(Expression.Not(Expression.Invoke(_inner.ToExpression(), p)), p);
    }
    public override string Describe() => $"NOT {_inner.Describe()}";
}

// --- the domain ---
public class Customer
{
    public string Name; public decimal LifetimeValue; public bool Blocked; public int MonthsSinceLastOrder;
    public override string ToString() => $"{Name,-8} value={LifetimeValue,7:0.00} blocked={Blocked,-5} dormant={MonthsSinceLastOrder}m";
}

// --- named business rules, each testable on its own ---
public class HighValue : Specification<Customer>
{
    private readonly decimal _threshold;
    public HighValue(decimal threshold) { _threshold = threshold; }
    public override Expression<Func<Customer, bool>> ToExpression() => c => c.LifetimeValue >= _threshold;
    public override string Describe() => $"lifetime value >= {_threshold}";
}

public class Blocked : Specification<Customer>
{
    public override Expression<Func<Customer, bool>> ToExpression() => c => c.Blocked;
    public override string Describe() => "blocked";
}

public class Dormant : Specification<Customer>
{
    public override Expression<Func<Customer, bool>> ToExpression() => c => c.MonthsSinceLastOrder >= 6;
    public override string Describe() => "no order in 6 months";
}

public static class Program
{
    public static void Main()
    {
        var customers = new List<Customer>
        {
            new Customer { Name = "Acme",   LifetimeValue = 12000m, Blocked = false, MonthsSinceLastOrder = 1 },
            new Customer { Name = "Globex", LifetimeValue = 15000m, Blocked = true,  MonthsSinceLastOrder = 2 },
            new Customer { Name = "Initech",LifetimeValue =  9000m, Blocked = false, MonthsSinceLastOrder = 8 },
            new Customer { Name = "Umbrella",LifetimeValue =   500m, Blocked = false, MonthsSinceLastOrder = 9 },
        };

        // The sentence the business actually said, assembled from named parts.
        var winBackTarget = new HighValue(5000m).And(new Dormant()).And(new Blocked().Not());

        Console.WriteLine("rule: " + winBackTarget.Describe());
        Console.WriteLine();

        Console.WriteLine("checked one at a time (in memory):");
        foreach (var c in customers)
            Console.WriteLine($"  {(winBackTarget.IsSatisfiedBy(c) ? "MATCH" : "     ")} {c}");

        Console.WriteLine();
        Console.WriteLine("the same specification used as a query predicate:");
        foreach (var c in customers.AsQueryable().Where(winBackTarget.ToExpression()))
            Console.WriteLine("  " + c.Name);

        Console.WriteLine();
        Console.WriteLine("reusing one part elsewhere, with no duplication:");
        foreach (var c in customers.AsQueryable().Where(new Blocked().ToExpression()))
            Console.WriteLine("  blocked: " + c.Name);
    }
}
```

**Output**

```
rule: ((lifetime value >= 5000 AND no order in 6 months) AND NOT blocked)

checked one at a time (in memory):
        Acme     value=12000.00 blocked=False dormant=1m
        Globex   value=15000.00 blocked=True  dormant=2m
  MATCH Initech  value=9000.00 blocked=False dormant=8m
        Umbrella value= 500.00 blocked=False dormant=9m

the same specification used as a query predicate:
  Initech

reusing one part elsewhere, with no duplication:
  blocked: Globex
```

**Interview memory:** One rule, one object, one name - and And/Or/Not for free. Build it from Expression, not Func, or EF cannot translate it.

**Interview answer:** A Result type makes failure part of the method's return type instead of an invisible side channel. The caller cannot ignore it without the compiler or a code review noticing, and the failure reason is data rather than a stack trace.

The rule I would give: **exceptions for the exceptional, results for the expected.** A database being unreachable is exceptional - throw. A user submitting an email address that is already registered is an ordinary Tuesday - return a result. Using exceptions for expected outcomes turns validation into control flow, which is both slow (exception throw and unwind cost is orders of magnitude above a return) and hard to read.

**What to say while explaining:** name the costs honestly. Result types need mapping at every boundary, they do not compose well with existing framework APIs that throw, and without a language-level match they get verbose. That is why teams adopt them for the domain layer and leave infrastructure throwing.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Diagnostics;

public class Result<T>
{
    public bool IsSuccess { get; }
    public T Value { get; }
    public string Error { get; }
    public string Code { get; }

    private Result(bool ok, T value, string code, string error)
    { IsSuccess = ok; Value = value; Code = code; Error = error; }

    public static Result<T> Ok(T value) => new Result<T>(true, value, null, null);
    public static Result<T> Fail(string code, string error) => new Result<T>(false, default(T), code, error);

    // Composition: chain only runs on success, so the failure short-circuits.
    public Result<TNext> Then<TNext>(Func<T, Result<TNext>> next) =>
        IsSuccess ? next(Value) : Result<TNext>.Fail(Code, Error);

    public override string ToString() => IsSuccess ? $"Ok({Value})" : $"Fail({Code}: {Error})";
}

public class User { public string Email; public override string ToString() => Email; }

public static class Registration
{
    private static readonly HashSet<string> Existing = new HashSet<string> { "taken@example.com" };

    // --- exception style ---
    public static User RegisterThrowing(string email)
    {
        if (string.IsNullOrWhiteSpace(email)) throw new ArgumentException("email is required");
        if (!email.Contains("@")) throw new FormatException("email is malformed");
        if (Existing.Contains(email)) throw new InvalidOperationException("email already registered");
        return new User { Email = email };
    }

    // --- result style ---
    public static Result<string> Validate(string email)
    {
        if (string.IsNullOrWhiteSpace(email)) return Result<string>.Fail("required", "email is required");
        if (!email.Contains("@")) return Result<string>.Fail("malformed", "email is malformed");
        return Result<string>.Ok(email);
    }

    public static Result<User> Register(string email) =>
        Validate(email).Then(valid =>
            Existing.Contains(valid)
                ? Result<User>.Fail("duplicate", "email already registered")
                : Result<User>.Ok(new User { Email = valid }));
}

public static class Program
{
    public static void Main()
    {
        var inputs = new[] { "new@example.com", "", "not-an-email", "taken@example.com" };

        Console.WriteLine("result style - every outcome is a return value:");
        foreach (var input in inputs)
            Console.WriteLine($"  '{input,-18}' -> {Registration.Register(input)}");

        Console.WriteLine();
        Console.WriteLine("exception style - the caller must know what to catch:");
        foreach (var input in inputs)
        {
            try { Console.WriteLine($"  '{input,-18}' -> Ok({Registration.RegisterThrowing(input)})"); }
            catch (Exception ex) { Console.WriteLine($"  '{input,-18}' -> {ex.GetType().Name}: {ex.Message}"); }
        }

        Console.WriteLine();
        Console.WriteLine("cost of using exceptions for an expected outcome (20,000 rejected inputs):");

        var sw = Stopwatch.StartNew();
        for (int i = 0; i < 20000; i++) Registration.Register("");
        var resultMs = sw.Elapsed.TotalMilliseconds;

        sw.Restart();
        for (int i = 0; i < 20000; i++)
        { try { Registration.RegisterThrowing(""); } catch (ArgumentException) { } }
        var throwMs = sw.Elapsed.TotalMilliseconds;

        // Printing the measured ratio would make this output machine-dependent,
        // so assert only the thing that is reliably true.
        Console.WriteLine($"  is the result path faster? {throwMs > resultMs}");
        Console.WriteLine("  (throwing and catching costs microseconds; returning costs nanoseconds)");
    }
}
```

**Output**

```
result style - every outcome is a return value:
  'new@example.com   ' -> Ok(new@example.com)
  '                  ' -> Fail(required: email is required)
  'not-an-email      ' -> Fail(malformed: email is malformed)
  'taken@example.com ' -> Fail(duplicate: email already registered)

exception style - the caller must know what to catch:
  'new@example.com   ' -> Ok(new@example.com)
  '                  ' -> ArgumentException: email is required
  'not-an-email      ' -> FormatException: email is malformed
  'taken@example.com ' -> InvalidOperationException: email already registered

cost of using exceptions for an expected outcome (20,000 rejected inputs):
  is the result path faster? True
  (throwing and catching costs microseconds; returning costs nanoseconds)
```

**Interview memory:** Exceptions for the exceptional, results for the expected. If the failure is in your acceptance criteria, it is a return value.

**Interview answer:** The Outbox pattern solves the dual-write problem: you need to save a row *and* publish a message, and there is no transaction spanning your database and your broker. Whichever you do second can fail, so you either save an order nobody is told about, or announce an order that was never saved.

The fix is to stop writing to two systems. Insert the message into an `Outbox` table **in the same database transaction** as the business data. A separate process then reads unpublished rows and pushes them to the broker, marking them sent. The transaction guarantees the message exists if and only if the order exists.

What this buys you is **at-least-once** delivery, not exactly-once. The publisher can crash after sending and before marking the row, so the message goes twice. Consumers must therefore be idempotent - that is the sentence interviewers wait for.

**What to say while explaining:** walk the crash points. The output below crashes the publisher between send and mark, and shows the duplicate that results, then shows the consumer absorbing it.

**Program**

```csharp
using System;
using System.Collections.Generic;
using System.Linq;

public class OutboxMessage
{
    public Guid Id; public string Type; public string Payload; public bool Published;
}

// Stands in for one relational database. A transaction covers BOTH tables.
public class Database
{
    public List<string> Orders = new List<string>();
    public List<OutboxMessage> Outbox = new List<OutboxMessage>();

    public void Transaction(Action work)
    {
        var ordersBefore = Orders.Count;
        var outboxBefore = Outbox.Count;
        try { work(); }
        catch
        {
            Orders.RemoveRange(ordersBefore, Orders.Count - ordersBefore);
            Outbox.RemoveRange(outboxBefore, Outbox.Count - outboxBefore);
            Console.WriteLine("    [db] rolled back - neither the order nor the outbox row survived");
            throw;
        }
    }
}

public class Broker
{
    public List<string> Delivered = new List<string>();
    public void Send(OutboxMessage m) { Delivered.Add(m.Payload); Console.WriteLine($"    [broker] received {m.Payload}"); }
}

public static class Program
{
    static readonly Guid Fixed1 = new Guid("11111111-1111-1111-1111-111111111111");
    static readonly Guid Fixed2 = new Guid("22222222-2222-2222-2222-222222222222");

    static void PlaceOrder(Database db, string order, Guid messageId, bool failAfterInsert)
    {
        db.Transaction(() =>
        {
            db.Orders.Add(order);
            db.Outbox.Add(new OutboxMessage { Id = messageId, Type = "OrderPlaced", Payload = order });
            Console.WriteLine($"    [db] inserted order and outbox row in ONE transaction");
            if (failAfterInsert) throw new Exception("crash before commit");
        });
    }

    // The relay: reads unpublished rows, sends, then marks. Crash-safe by design.
    static void RunPublisher(Database db, Broker broker, bool crashBeforeMarking)
    {
        foreach (var message in db.Outbox.Where(m => !m.Published).ToList())
        {
            broker.Send(message);
            if (crashBeforeMarking)
            {
                Console.WriteLine("    [publisher] CRASHED before marking the row as published");
                return;
            }
            message.Published = true;
        }
    }

    public static void Main()
    {
        var db = new Database();
        var broker = new Broker();

        Console.WriteLine("1. a successful order:");
        PlaceOrder(db, "ORD-1", Fixed1, failAfterInsert: false);

        Console.WriteLine("2. an order whose transaction fails:");
        try { PlaceOrder(db, "ORD-2", Fixed2, failAfterInsert: true); } catch { }
        Console.WriteLine($"   orders={db.Orders.Count} outbox={db.Outbox.Count}  (no half state is possible)");

        Console.WriteLine();
        Console.WriteLine("3. the publisher runs and crashes after sending, before marking:");
        RunPublisher(db, broker, crashBeforeMarking: true);

        Console.WriteLine("4. the publisher restarts and retries the still-unpublished row:");
        RunPublisher(db, broker, crashBeforeMarking: false);

        Console.WriteLine();
        Console.WriteLine($"broker received {broker.Delivered.Count} copies of {broker.Delivered.Distinct().Count()} distinct message(s)");
        Console.WriteLine("this is at-least-once delivery, which is why consumers MUST be idempotent:");

        var processed = new HashSet<string>();
        foreach (var payload in broker.Delivered)
        {
            if (processed.Add(payload)) Console.WriteLine($"    [consumer] handled {payload}");
            else Console.WriteLine($"    [consumer] already handled {payload} - ignored");
        }
    }
}
```

**Output**

```
1. a successful order:
    [db] inserted order and outbox row in ONE transaction
2. an order whose transaction fails:
    [db] inserted order and outbox row in ONE transaction
    [db] rolled back - neither the order nor the outbox row survived
   orders=1 outbox=1  (no half state is possible)

3. the publisher runs and crashes after sending, before marking:
    [broker] received ORD-1
    [publisher] CRASHED before marking the row as published
4. the publisher restarts and retries the still-unpublished row:
    [broker] received ORD-1

broker received 2 copies of 1 distinct message(s)
this is at-least-once delivery, which is why consumers MUST be idempotent:
    [consumer] handled ORD-1
    [consumer] already handled ORD-1 - ignored
```

**Interview memory:** Never write to the database and the broker separately. Write the message into the database, and let something else move it.

**Interview answer:** A circuit breaker stops calling a dependency that is already failing. After a threshold of consecutive failures it **opens** and fails fast without making the call at all; after a cooldown it goes **half-open** and lets a single trial request through; if that succeeds it **closes**, otherwise it opens again.

Retry alone makes an outage worse. If a downstream service is overloaded, every caller retrying three times triples the load on the thing that is already drowning, and each caller holds a thread or connection for the full timeout while doing it. The breaker is what converts a slow cascading failure into a fast local one.

The pairing to state: **breaker first, retry inside it, timeout inside that.** Retry handles a blip, the breaker handles an outage, and the timeout stops any single call pinning a resource.

**What to say while explaining:** note that the demo injects a clock. A resilience component that reads `DateTime.UtcNow` directly is untestable, which is the sort of detail that tends to earn credit.

**Program**

```csharp
using System;

public enum CircuitState { Closed, Open, HalfOpen }

// An injected clock, so the cooldown is testable without sleeping.
public class FakeClock
{
    public DateTime UtcNow { get; private set; } = new DateTime(2026, 1, 1, 12, 0, 0, DateTimeKind.Utc);
    public void Advance(TimeSpan by) => UtcNow = UtcNow.Add(by);
}

public class CircuitBreakerOpenException : Exception
{
    public CircuitBreakerOpenException(string message) : base(message) { }
}

public class CircuitBreaker
{
    private readonly int _threshold;
    private readonly TimeSpan _cooldown;
    private readonly FakeClock _clock;

    private int _consecutiveFailures;
    private DateTime _openedAt;

    public CircuitState State { get; private set; } = CircuitState.Closed;

    public CircuitBreaker(int threshold, TimeSpan cooldown, FakeClock clock)
    { _threshold = threshold; _cooldown = cooldown; _clock = clock; }

    public T Execute<T>(Func<T> action)
    {
        if (State == CircuitState.Open)
        {
            if (_clock.UtcNow - _openedAt < _cooldown)
                throw new CircuitBreakerOpenException("circuit is open - failing fast, the call was NOT made");

            State = CircuitState.HalfOpen;      // cooldown elapsed: allow one trial call
        }

        try
        {
            var result = action();
            Reset();
            return result;
        }
        catch (CircuitBreakerOpenException) { throw; }
        catch
        {
            RecordFailure();
            throw;
        }
    }

    private void Reset()
    {
        if (State == CircuitState.HalfOpen) Console.WriteLine("    [breaker] trial call succeeded -> Closed");
        _consecutiveFailures = 0;
        State = CircuitState.Closed;
    }

    private void RecordFailure()
    {
        _consecutiveFailures++;
        // A failure while half-open re-opens immediately, without waiting for the threshold.
        if (State == CircuitState.HalfOpen || _consecutiveFailures >= _threshold)
        {
            State = CircuitState.Open;
            _openedAt = _clock.UtcNow;
            Console.WriteLine($"    [breaker] -> Open (failures={_consecutiveFailures})");
        }
    }
}

public static class Program
{
    static int _callsActuallyMade;
    static bool _dependencyHealthy;

    static string CallDependency()
    {
        _callsActuallyMade++;
        if (!_dependencyHealthy) throw new TimeoutException("downstream timed out");
        return "200 OK";
    }

    static void Try(CircuitBreaker breaker, string label)
    {
        try { Console.WriteLine($"  {label}: {breaker.Execute(CallDependency)}  [state={breaker.State}]"); }
        catch (CircuitBreakerOpenException ex) { Console.WriteLine($"  {label}: {ex.Message}  [state={breaker.State}]"); }
        catch (Exception ex) { Console.WriteLine($"  {label}: {ex.Message}  [state={breaker.State}]"); }
    }

    public static void Main()
    {
        var clock = new FakeClock();
        var breaker = new CircuitBreaker(threshold: 3, cooldown: TimeSpan.FromSeconds(30), clock: clock);

        _dependencyHealthy = true;
        Console.WriteLine("dependency healthy:");
        Try(breaker, "call 1");

        _dependencyHealthy = false;
        Console.WriteLine("dependency starts failing:");
        Try(breaker, "call 2");
        Try(breaker, "call 3");
        Try(breaker, "call 4");

        Console.WriteLine("further calls while open - note these never reach the dependency:");
        Try(breaker, "call 5");
        Try(breaker, "call 6");

        Console.WriteLine($"calls actually made so far: {_callsActuallyMade}");

        Console.WriteLine();
        Console.WriteLine("30 seconds pass, dependency is still down:");
        clock.Advance(TimeSpan.FromSeconds(31));
        Try(breaker, "call 7");

        Console.WriteLine("30 more seconds pass, dependency has recovered:");
        clock.Advance(TimeSpan.FromSeconds(31));
        _dependencyHealthy = true;
        Try(breaker, "call 8");
        Try(breaker, "call 9");

        Console.WriteLine();
        Console.WriteLine($"9 attempts, but only {_callsActuallyMade} reached the dependency.");
    }
}
```

