**Interview memory:** Exponential backoff protects the dependency. Jitter protects it from your other instances. Idempotency protects the user.

**Interview answer:** Decorator is the natural way to add caching, logging, retry or metrics to a service without touching it - the decorator implements the same interface, wraps the real one, and callers cannot tell the difference.

The catch specific to .NET is that the built-in container has **no `Decorate` method**. You wire it yourself with a factory registration: register the concrete implementation, then register the interface as a lambda that resolves the concrete type and wraps it. Scrutor's `services.Decorate<IService, CachingDecorator>()` does exactly this, and knowing it is a library rather than a framework feature is often the actual question.

**What to say while explaining:** order matters and the registration order determines it. The output shows caching outside logging, which means a cache hit is never logged as a call - usually not what you want.

**Program**

```csharp
using System;
using System.Collections.Generic;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.DependencyInjection;

public interface IProductService { string GetName(int id); }

public class ProductService : IProductService
{
    public int DatabaseHits { get; private set; }

    public string GetName(int id)
    {
        DatabaseHits++;
        Console.WriteLine($"      [database] SELECT name FROM Products WHERE Id = {id}");
        return "Product-" + id;
    }
}

public class LoggingProductService : IProductService
{
    private readonly IProductService _inner;
    public LoggingProductService(IProductService inner) { _inner = inner; }

    public string GetName(int id)
    {
        Console.WriteLine($"    [log] GetName({id}) starting");
        var result = _inner.GetName(id);
        Console.WriteLine($"    [log] GetName({id}) returned '{result}'");
        return result;
    }
}

public class CachingProductService : IProductService
{
    private readonly IProductService _inner;
    private readonly IMemoryCache _cache;
    public CachingProductService(IProductService inner, IMemoryCache cache) { _inner = inner; _cache = cache; }

    public string GetName(int id)
    {
        if (_cache.TryGetValue(id, out string cached))
        {
            Console.WriteLine($"  [cache] hit for {id}");
            return cached;
        }
        Console.WriteLine($"  [cache] miss for {id}");
        var value = _inner.GetName(id);
        _cache.Set(id, value);
        return value;
    }
}

public static class Program
{
    public static void Main()
    {
        var services = new ServiceCollection();
        services.AddMemoryCache();

        // Register the concrete type so the decorators can resolve it.
        services.AddSingleton<ProductService>();

        // Build the chain by hand: cache -> log -> real service.
        services.AddSingleton<IProductService>(sp =>
            new CachingProductService(
                new LoggingProductService(sp.GetRequiredService<ProductService>()),
                sp.GetRequiredService<IMemoryCache>()));

        var provider = services.BuildServiceProvider();
        var service = provider.GetRequiredService<IProductService>();
        var real = provider.GetRequiredService<ProductService>();

        Console.WriteLine("callers only ever see IProductService:");
        Console.WriteLine($"  resolved type: {service.GetType().Name}");
        Console.WriteLine();

        Console.WriteLine("first call for id 7:");
        service.GetName(7);
        Console.WriteLine("second call for id 7:");
        service.GetName(7);
        Console.WriteLine("first call for id 9:");
        service.GetName(9);

        Console.WriteLine();
        Console.WriteLine($"database was hit {real.DatabaseHits} time(s) for 3 calls");
        Console.WriteLine("note the cache hit produced NO log line - caching sits outside logging,");
        Console.WriteLine("so served-from-cache calls are invisible to the logger. Swap the order to change that.");
    }
}
```

**Output**

```
