  resolved type: CachingProductService

first call for id 7:
  [cache] miss for 7
    [log] GetName(7) starting
      [database] SELECT name FROM Products WHERE Id = 7
    [log] GetName(7) returned 'Product-7'
second call for id 7:
  [cache] hit for 7
first call for id 9:
  [cache] miss for 9
